func registerIDLRoutes(h *hertzserver.Hertz) {
	h.GET("/health", Health)
	h.POST("/api/agent/register", RegisterAgent)
	h.POST("/api/agent/status", AgentAuth(), ReportAgentStatus)
	h.GET("/api/agent/mailbox", AgentAuth(), PullMailbox)
	h.POST("/api/agent/messages/offset", AgentAuth(), UpdateMailboxOffset)
	h.POST("/api/agent/messages/:messageId/result", AgentAuth(), ReportMessageResult)
	h.GET("/api/user/agents", ListAgents)
	h.GET("/api/user/agents/:agentId/sessions", ListAgentSessions)
	h.GET("/api/user/sessions/:sessionId", GetSession)
	h.GET("/api/user/sessions/:sessionId/messages", ListSessionMessages)
	h.POST("/api/user/message", CreateMailboxMessage)
	h.GET("/api/user/mailbox", ListMailbox)
	h.GET("/api/user/api-keys", ListUserAPIKeys)
	h.POST("/api/user/api-keys", CreateUserAPIKey)
	h.DELETE("/api/user/api-keys/:keyId", RevokeUserAPIKey)
	h.POST("/api/user/agent-registration-tokens", CreateAgentRegistrationToken)
}

